{"tool": "write_file", "args": {"path": "scripts/resend_failed_sms.py", "content": """"LIFE-209: re-send SMS messages that failed during cycle 1.

Reads data/sms_status.json to find failed vs delivered messages, fetches the
original message details from data/outbox/sms.jsonl, re-sends each failed
message via the existing send function in notifications/sms.py, and appends
audit entries to data/audit.jsonl. Idempotent: skips messages that already
appear to have been resent (duplicate household+message in the outbox).
"""
import json
import os
import sys
import traceback

BASE = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
if BASE not in sys.path:
    sys.path.insert(0, BASE)

STATUS_PATH = os.path.join(BASE, "data", "sms_status.json")
OUTBOX_PATH = os.path.join(BASE, "data", "outbox", "sms.jsonl")
AUDIT_PATH = os.path.join(BASE, "data", "audit.jsonl")

FAILED_STATUSES = {"failed", "error", "undelivered", "failure", "bounce", "bounced"}
DELIVERED_STATUSES = {"delivered", "sent", "ok", "success"}


def load_status_records():
    with open(STATUS_PATH) as f:
        data = json.load(f)
    if isinstance(data, list):
        return data
    if isinstance(data, dict):
        # e.g. {"failed": [ids...], "delivered": [ids...]}
        if isinstance(data.get("failed"), list):
            recs = []
            for i in data.get("failed", []):
                recs.append({"id": i, "status": "failed"} if not isinstance(i, dict) else dict(i, status=i.get("status", "failed")))
            for i in data.get("delivered", []):
                recs.append({"id": i, "status": "delivered"} if not isinstance(i, dict) else dict(i, status=i.get("status", "delivered")))
            return recs
        for key in ("messages", "statuses", "records", "items", "sms"):
            if isinstance(data.get(key), list):
                return data[key]
        records = []
        for k, v in data.items():
            if isinstance(v, dict):
                rec = dict(v)
                rec.setdefault("id", k)
            else:
                rec = {"id": k, "status": v}
            records.append(rec)
        return records
    raise ValueError("Unrecognized sms_status.json format")


def rec_id(r):
    for key in ("id", "message_id", "msg_id", "sms_id"):
        if key in r and r[key] is not None:
            return r[key]
    return None


def rec_status(r):
    for key in ("status", "state", "result", "delivery_status"):
        if key in r and r[key] is not None:
            return str(r[key]).strip().lower()
    return ""


def field(d, keys):
    for k in keys:
        if k in d and d[k] is not None:
            return d[k]
    return None


def main():
    records = load_status_records()
    failed_ids = set()
    delivered_ids = set()
    status_records_by_id = {}
    for r in records:
        rid = rec_id(r)
        st = rec_status(r)
        if rid is not None:
            status_records_by_id[rid] = r
        if st in FAILED_STATUSES:
            failed_ids.add(rid)
        elif st in DELIVERED_STATUSES:
            delivered_ids.add(rid)

    # Load original messages from the outbox (JSONL).
    originals = {}
    outbox_lines = []
    with open(OUTBOX_PATH) as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            msg = json.loads(line)
            outbox_lines.append(msg)
            mid = rec_id(msg)
            if mid in failed_ids and mid not in originals:
                originals[mid] = msg

    # Fallback: status records may carry the full message themselves.
    for mid in failed_ids:
        if mid not in originals and mid in status_records_by_id:
            r = status_records_by_id[mid]
            if field(r, ("household", "household_id", "recipient", "to")) and field(r, ("message", "text", "body", "content")):
                originals[mid] = r

    # Idempotency guard: count outbox occurrences of (household, message).
    def pair(msg):
        h = field(msg, ("household", "household_id", "recipient", "to"))
        m = field(msg, ("message", "text", "body", "content"))
        return (json.dumps(h, sort_keys=True), json.dumps(m, sort_keys=True))

    pair_counts = {}
    for msg in outbox_lines:
        pair_counts.setdefault(pair(msg), 0)
        pair_counts[pair(msg)] += 1

    # Reuse the existing send function from notifications/sms.py.
    import notifications.sms as sms_mod
    send_fn = None
    for name in ("send_sms", "send", "send_text", "send_message", "send_text_message"):
        fn = getattr(sms_mod, name, None)
        if callable(fn):
            send_fn = fn
            break
    if send_fn is None:
        for name in dir(sms_mod):
            if "send" in name.lower() and callable(getattr(sms_mod, name)):
                send_fn = getattr(sms_mod, name)
                break
    if send_fn is None:
        raise RuntimeError("No send function found in notifications/sms.py")

    def do_send(household, message, details):
        attempts = [
            lambda: send_fn(household=household, message=message, details=details),
            lambda: send_fn(household, message, details),
            lambda: send_fn(household, message),
            lambda: send_fn(household=household, message=message),
            lambda: send_fn(household_id=household, message=message),
            lambda: send_fn(household_id=household, text=message),
            lambda: send_fn(to=household, message=message),
            lambda: send_fn(to=household, text=message),
            lambda: send_fn(recipient=household, message=message),
            lambda: send_fn(recipient=household, text=message),
            lambda: send_fn(number=household, message=message),
            lambda: send_fn(household, text=message),
            lambda: send_fn({"household": household, "message": message, "details": details}),
            lambda: send_fn({"household_id": household, "text": message, "details": details}),
            lambda: send_fn(message),
        ]
        last_err = None
        for a in attempts:
            try:
                return a()
            except TypeError as e:
                last_err = e
                continue
            except Exception as e:
                # Non-TypeError means the call matched but sending failed.
                raise
        raise last_err

    sent = []
    errors = []
    for mid in sorted(failed_ids, key=str):
        if mid not in originals:
            errors.append("no original message found for failed id %r" % (mid,))
            continue
        msg = originals[mid]
        household = field(msg, ("household", "household_id", "recipient", "to"))
        message = field(msg, ("message", "text", "body", "content"))
        details = msg.get("details")
        # Skip if this household+message already appears more than once
        # (i.e. a resend from a previous partial run already happened).
        if pair_counts.get(pair(msg), 0) >= 2:
            print("SKIP id=%r: already resent previously" % (mid,))
            continue
        try:
            do_send(household, message, details)
        except Exception as e:
            errors.append("send failed for id=%r: %r" % (mid, e))
            continue
        pair_counts[pair(msg)] = pair_counts.get(pair(msg), 0) + 1
        sent.append({"message_id": mid, "household": household, "message": message, "details": details})

    # Append audit entries consistent with the existing audit log.
    try:
        existing_keys = set()
        if os.path.exists(AUDIT_PATH):
            with open(AUDIT_PATH) as f:
                for line in f:
                    line = line.strip()
                    if line:
                        try:
                            existing_keys.update(json.loads(line).keys())
                        except Exception:
                            pass
        with open(AUDIT_PATH, "a") as f:
            for s in sent:
                entry = {}
                if "action" in existing_keys or not existing_keys:
                    entry["action"] = "resend_failed_sms"
                if "event" in existing_keys:
                    entry["event"] = "resend_failed_sms"
                if "type" in existing_keys:
                    entry["type"] = "sms_resend"
                if "message_id" in existing_keys or "id" in existing_keys:
                    entry["message_id"] = s["message_id"]
                if "household" in existing_keys or "household_id" in existing_keys:
                    entry["household"] = s["household"]
                if "message" in existing_keys or "text" in existing_keys:
                    entry["message"] = s["message"]
                if "details" in existing_keys:
                    entry["details"] = s["details"]
                if "status" in existing_keys:
                    entry["status"] = "resent"
                if not entry:
                    entry = {"action": "resend_failed_sms", "message_id": s["message_id"], "household": s["household"]}
                f.write(json.dumps(entry) + "\n")
    except Exception:
        traceback.print_exc()

    print("Resent %d failed message(s):" % len(sent))
    for s in sent:
        print("  - id=%r household=%r" % (s["message_id"], s["household"]))
    print("Delivered households skipped: %d" % len(delivered_ids))
    if errors:
        print("ERRORS:")
        for e in errors:
            print("  - " + e)
        sys.exit(1)


if __name__ == "__main__":
    main()
